import numpy as np,wave
for name in ['drums','bass','chords','lead','arp','bells','glides']:
 w=wave.open('/workspace/work/'+name+'.wav','rb');x=np.frombuffer(w.readframes(w.getnframes()),'<i2').reshape(-1,2).mean(axis=1)/32768
 size=8192;acc=np.zeros(size//2+1)
 for k in range(293760,len(x)-293760,size//2):
  z=np.fft.rfft(x[k:k+size]*np.hanning(size));acc+=abs(z)**2
 f=np.fft.rfftfreq(size,1/44100)
 print(name,'power shares',np.round([np.sum(acc[(f>=l)&(f<u)])/sum(acc) for l,u in [(0,150),(150,500),(500,2000),(2000,5000),(5000,22050)]],3), 'centroid',round(np.sum(acc*f)/sum(acc)))
